#define CACHE_LINE_SIZE 64

// Data Alignment to prevent False Sharing in multi-threading
// Ensures count sits alone on a 64-byte boundary
struct alignas(CACHE_LINE_SIZE) ThreadCounter {
    long count;
};

// Or manual padding (C style)
struct ThreadTask {
    int id;
    long status;
    char padding[CACHE_LINE_SIZE - sizeof(int) - sizeof(long)];
};
